package it.plannershop.common;

import java.security.SecureRandom;

/** Temporary passwords generated by the system (first start-up, password reset). */
public final class RandomPassword {

    /** No ambiguous characters (0/O, 1/l/I), so it can be read aloud or copied by hand. */
    private static final String ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
    private static final SecureRandom RANDOM = new SecureRandom();

    private RandomPassword() {
    }

    public static String generate() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 16; i++) {
            sb.append(ALPHABET.charAt(RANDOM.nextInt(ALPHABET.length())));
        }
        return sb.toString();
    }
}
